export default function matomoPrompt({ body }) {
  if (!Array.isArray(body)) throw Error("Matomo did not return a visit list");
  if (body.length > 100) throw Error("Matomo exceeded the 100-visit limit");
  if (!body.length) return { hasVisits: false, messages: [] };
  const lines = body
    .map((v) => {
      if (
        typeof v?.visitorId !== "string" ||
        !v.visitorId ||
        !Number.isFinite(Number(v.visitCount)) ||
        !Array.isArray(v.actionDetails)
      )
        throw Error("Invalid Matomo visit");
      const actions = v.actionDetails
        .map((a) => {
          if (!a || typeof a !== "object" || Array.isArray(a)) throw Error("Invalid Matomo action");
          return `  - Page ${a.pageviewPosition ?? "not provided"}: ${a.pageTitle ?? "not provided"}\n    URL: ${a.url ?? "not provided"}\n    Time Spent: ${a.timeSpentPretty ?? "not provided"}`;
        })
        .join("\n");
      return `- Visitor (ID: ${v.visitorId}):\n  Visit Count: ${v.visitCount}\n${actions}`;
    })
    .join("\n\n");
  const content = `You are an SEO expert. Please analyze this visitor data:\n\n${lines}\n\nPlease provide insights on:\n1. Common visitor paths\n2. Popular pages\n3. User engagement patterns\n4. Recommendations for improvement`;
  return { hasVisits: true, messages: [{ role: "user", content }] };
}

