export default function reportRow({ completion, blog }) {
  if (typeof blog !== "string" || !blog.trim() || blog === "YOUR_BLOG_NAME")
    throw Error("Configure the blog name");
  const text = completion?.choices?.[0]?.message?.content;
  if (typeof text !== "string" || !text.trim()) throw Error("OpenRouter returned no report text");
  if (completion.choices[0].finish_reason === "length")
    throw Error("OpenRouter report was truncated");
  return { row: { Date: new Date().toISOString().slice(0, 10), Note: text, Blog: blog } };
}
